package com.bank.devsecops;

import java.util.List;
import java.util.logging.Logger;

public class PipelineSecurityDemo {
    private static final Logger log = Logger.getLogger(PipelineSecurityDemo.class.getName());

    public static void main(String[] args) {
        log.info("Bank: National Bank of India — shift-left pipeline simulator");

        // A commit that accidentally hardcodes a DB password (the classic mistake).
        CommitArtifact commit = new CommitArtifact("PAY-1421");
        commit.setHasHardcodedSecret(true);

        // Stages ordered LEFT (cheapest, earliest) to RIGHT (later, costlier).
        List<SecurityStage> pipeline = List.of(
            new SecurityStage("pre-commit secret scan", 1, c -> !c.hasHardcodedSecret()),
            new SecurityStage("build-time SAST", 10, c -> !c.hasInjectionFlaw()),
            new SecurityStage("build-time SCA (deps)", 10, c -> !c.hasVulnerableDependency()),
            new SecurityStage("dynamic test (DAST)", 100, c -> !c.hasRuntimeAuthGap())
        );

        for (SecurityStage stage : pipeline) {
            boolean passed = stage.evaluate(commit);
            if (!passed) {
                log.severe(() -> "FAIL FAST at '" + stage.name() + "' (relative fix cost "
                        + stage.relativeFixCost() + "x). Caught early = cheap to fix.");
                log.info("Developer fixes it now, in context; insecure code never ships.");
                return; // fail the pipeline at the earliest detecting stage
            }
            log.info(() -> "PASS: " + stage.name());
        }
        log.info("All security stages passed — safe to deploy");
    }
}

