package com.bank.devsecops;

import java.util.function.Predicate;

class SecurityStage {
    private final String name;
    private final int relativeFixCost; // how much costlier a miss becomes if found later
    private final Predicate<CommitArtifact> check;

    SecurityStage(String name, int relativeFixCost, Predicate<CommitArtifact> check) {
        this.name = name;
        this.relativeFixCost = relativeFixCost;
        this.check = check;
    }
    String name() { return name; }
    int relativeFixCost() { return relativeFixCost; }
    boolean evaluate(CommitArtifact commit) { return check.test(commit); }
}
